461:     static parseChunkToInt(intBytes: Buffer, minByteLen: number, maxByteLen: number, raise_on_Null = false) {
462:         // # Parse data as unsigned-big-endian encoded integer.
463:         // # For empty data different possibilities may occur:
464:         // #      minByteLen <= 0 : return 0
465:         // #      raise_on_Null == False and minByteLen > 0: return None
466:         // #      raise_on_Null == True and minByteLen > 0:  raise SlpInvalidOutputMessage
467:         if(intBytes.length >= minByteLen && intBytes.length <= maxByteLen)
468:             return intBytes.readUIntBE(0, intBytes.length)
469:         if(intBytes.length === 0 && !raise_on_Null)
470:             return null;
471:         throw Error('Field has wrong length');
